 44	/** Keeps the reservations in memory: everything is lost when the service restarts. */
 45	public final class ReservationStore {
 46	
 47	    private final Map<Long, Reservation> reservationsById = new LinkedHashMap<>();
 48	    private long lastId = 0;
 49	
 50	    synchronized long nextId() {
 51	        lastId++;
 52	        return lastId;
 53	    }
 54	
 55	    synchronized void save(Reservation reservation) {
 56	        reservationsById.put(reservation.id(), reservation);
 57	    }
