 72	public final class Reservation {
 73	
 74	    private final long id;
 75	    private final int roomNumber;
 76	    private final Guest guest;
 77	    private final LocalDate checkIn;
 78	    private final LocalDate checkOut;
 79	    private final int guests;
 80	    private final RatePlan ratePlan;
 81	    private final Price price;
 82	    private ReservationStatus status;
 83	    private BigDecimal amountPaid;
 84	    private BigDecimal refund;
 85	
 86	    Reservation(long id, NewReservation request, Price price) {
 87	        this.id = id;
 88	        this.roomNumber = request.roomNumber();
 89	        this.guest = request.guest();
 90	        this.checkIn = request.checkIn();
 91	        this.checkOut = request.checkOut();
 92	        this.guests = request.guests();
 93	        this.ratePlan = request.ratePlan();
 94	        this.price = price;
 95	        this.status = ReservationStatus.PENDING;
 96	        this.amountPaid = PriceCalculator.cents(BigDecimal.ZERO);
 97	    }
 98	
 99	    public long id() {
100	        return id;
101	    }
102	
103	    public int roomNumber() {
104	        return roomNumber;
105	    }
106	
107	    public Guest guest() {
108	        return guest;
109	    }
110	
111	    public LocalDate checkIn() {
112	        return checkIn;
113	    }
114	
115	    public LocalDate checkOut() {
116	        return checkOut;
117	    }
118	
119	    public int guests() {
120	        return guests;
121	    }
122	
123	    public RatePlan ratePlan() {
124	        return ratePlan;
125	    }
126	
127	    public Price price() {
128	        return price;
129	    }
130	
131	    public ReservationStatus status() {
132	        return status;
133	    }
134	
135	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
136	    public BigDecimal amountPaid() {
137	        return amountPaid;
138	    }
139	
140	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
141	    public BigDecimal refund() {
142	        return refund;
143	    }
144	
145	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
146	    public boolean isPaid() {
147	        return status == ReservationStatus.CONFIRMED
148	                || status == ReservationStatus.CHECKED_IN
149	                || status == ReservationStatus.CHECKED_OUT;
150	    }
151	
152	    /** The money the inn keeps from this reservation. */
153	    public BigDecimal amountKept() {
154	        return refund == null ? amountPaid : amountPaid.subtract(refund);
155	    }
156	
157	    void changeStatus(ReservationStatus newStatus) {
158	        this.status = newStatus;
159	    }
160	
161	    void confirmPayment() {
162	        this.status = ReservationStatus.CONFIRMED;
163	        this.amountPaid = price.total();
164	    }
165	
166	    void cancel(BigDecimal refundAmount) {
167	        this.status = ReservationStatus.CANCELLED;
168	        this.refund = refundAmount;
169	    }
170	
171	    boolean overlaps(int otherRoomNumber, LocalDate otherCheckIn, LocalDate otherCheckOut) {
172	        return roomNumber == otherRoomNumber
173	                && checkIn.isBefore(otherCheckOut)
174	                && otherCheckIn.isBefore(checkOut);
175	    }
